import re, collections

def transform(grid):
    a=[row[:] for row in grid]
    h,w=len(a),len(a[0])
    vals=collections.Counter(v for row in a for v in row)
    bg=vals.most_common(1)[0][0]
    active=[i for i,row in enumerate(a) if any(x!=bg for x in row)]
    groups=[]
    for r in active:
        if not groups or r>groups[-1][-1]+1: groups.append([r])
        else: groups[-1].append(r)
    pairs=[]
    for i,g1 in enumerate(groups):
      for g2 in groups[i+1:]:
        if len(g1)==len(g2):
          mismatch=sum(a[r1][c]!=a[r2][c] for r1,r2 in zip(g1,g2) for c in range(w))
          pairs.append((mismatch,g1,g2))
    if not pairs: return a
    mismatch,g1,g2=min((x for x in pairs if x[0]>0),default=(0,None,None),key=lambda x:x[0])
    if g1 is None:return a
    if len(g1)>1:
      for r1,r2 in zip(g1,g2):
       for c in range(w):
        if a[r1][c]!=a[r2][c]: a[r2][c]=1
    else:
      r1,r2=g1[0],g2[0]
      for c in range(w):
       if a[r1][c]!=a[r2][c]:
        if a[r1][c]==bg: a[r1][c]=1
        elif a[r2][c]==bg: a[r2][c]=1
        else: a[r1][c]=1
    return a

